## 五、实际应用场景说明

### 5.1 图像处理应用

**彩色图像转灰度图像**：

```c
// 图像灰度转换内核
__global__ void colorToGrayscale(unsigned char* grayImage,
                                  unsigned char* rgbImage,
                                  int width, int height) {
    // 计算像素的全局索引
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    // 边界检查
    if (x < width && y < height) {
        // 计算RGB像素的索引
        int grayIdx = y * width + x;
        int rgbIdx = grayIdx * 3;

        // 提取RGB分量
        unsigned char r = rgbImage[rgbIdx];     // 红色分量
        unsigned char g = rgbImage[rgbIdx + 1]; // 绿色分量
        unsigned char b = rgbImage[rgbIdx + 2]; // 蓝色分量

        // 计算灰度值（加权平均）
        // 人眼对不同颜色的敏感度不同
        grayImage[grayIdx] = 0.21f * r + 0.72f * g + 0.07f * b;
    }
}

// 主机调用代码
void processImage(unsigned char* h_rgbImage, 
                  unsigned char* h_grayImage,
                  int width, int height) {
    // 设备内存指针
    unsigned char *d_rgbImage, *d_grayImage;
    size_t rgbSize = width * height * 3 * sizeof(unsigned char);
    size_t graySize = width * height * sizeof(unsigned char);

    // 分配设备内存
    cudaMalloc(&d_rgbImage, rgbSize);
    cudaMalloc(&d_grayImage, graySize);

    // 传输输入图像
    cudaMemcpy(d_rgbImage, h_rgbImage, rgbSize, cudaMemcpyHostToDevice);

    // 配置二维网格和块
    dim3 blockDim(16, 16);  // 每块16x16=256个线程
    dim3 gridDim((width + 15) / 16, (height + 15) / 16);

    // 启动内核
    colorToGrayscale<<<gridDim, blockDim>>>(
        d_grayImage, d_rgbImage, width, height);

    // 回传结果
    cudaMemcpy(h_grayImage, d_grayImage, graySize, cudaMemcpyDeviceToHost);

    // 释放内存
    cudaFree(d_rgbImage);
    cudaFree(d_grayImage);
}
```

**应用特点**：
- 高度并行：每个像素独立处理
- 数据量大：百万级像素
- 计算简单：每个像素少量运算
- 适合GPU：大规模数据并行

