```c
// 矩阵向量乘法内核：y = A * x
__global__ void matrixVectorMul(float* A, float* x, float* y,
                                int numRows, int numCols) {
    // 每个线程计算输出向量的一个元素
    int row = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < numRows) {
        float sum = 0.0f;

        // 计算矩阵该行与向量的点积
        for (int col = 0; col < numCols; ++col) {
            sum += A[row * numCols + col] * x[col];
        }

        y[row] = sum;
    }
}
```

