- 更新原子位置和速度

**并行策略**：
```c
// 计算原子间作用力
__global__ void computeForces(Atom* atoms, int numAtoms) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < numAtoms) {
        float fx = 0.0f, fy = 0.0f, fz = 0.0f;

        // 计算原子i与所有其他原子的作用力
        for (int j = 0; j < numAtoms; ++j) {
            if (i != j) {
                // 计算距离
                float dx = atoms[j].x - atoms[i].x;
                float dy = atoms[j].y - atoms[i].y;
                float dz = atoms[j].z - atoms[i].z;
                float r = sqrt(dx*dx + dy*dy + dz*dz);

                // 计算力（简化示例）
                float force = computeForce(r);

                // 累加力的分量
                fx += force * dx / r;
                fy += force * dy / r;
                fz += force * dz / r;
            }
        }

        // 更新原子的受力
        atoms[i].fx = fx;
        atoms[i].fy = fy;
        atoms[i].fz = fz;
    }
}
```

### 5.4 深度学习应用

**卷积神经网络**：

```c
// 简化的卷积操作内核
__global__ void convolution(float* input, float* kernel, float* output,
                           int width, int height, int kernelSize) {
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if (x < width && y < height) {
        float sum = 0.0f;
        int halfKernel = kernelSize / 2;

        // 卷积计算
        for (int ky = -halfKernel; ky <= halfKernel; ++ky) {
            for (int kx = -halfKernel; kx <= halfKernel; ++kx) {
                int ix = x + kx;
                int iy = y + ky;

                // 边界处理（零填充）
                if (ix >= 0 && ix < width && iy >= 0 && iy < height) {
                    int inputIdx = iy * width + ix;
                    int kernelIdx = (ky + halfKernel) * kernelSize + 
                                   (kx + halfKernel);
                    sum += input[inputIdx] * kernel[kernelIdx];
                }
            }
        }

        output[y * width + x] = sum;
    }
}
```

